import randomNPC = 1540460ITEM_TRADE = 2433515ITEM_REQ = 10VON_BON = [    2591392, #Beefy Von Bon Soul"    2591393, #Swift Von Bon Soul"    2591394, #Clever Von Bon Soul"    2591395, #Fortuitous Von Bon Soul"    2591396, #Flashy Von Bon Soul"    2591397, #Potent Von Bon Soul"    2591398, #Radiant Von Bon Soul"    2591399, #Hearty Von Bon Soul"    2591400, #Magnificent Von Bon Soul"]PERCENT = random.randint(1,100)sm.setSpeakerID(NPC)sm.flipBoxChat()sm.setBoxChat()selection = sm.sendSay("You can trade required items for one of the following random items \r\n"                            "#L0##bSoul Exchange.#l\r\n"                            "#L1##bList Item.#l \r\n"                            "#L2##kNever mind.#l\r\n")if selection == 0:    if not sm.hasItem(ITEM_TRADE,ITEM_REQ):        req = "You need at least #r%s #i%s# #b#e#z%s##n#k" % (ITEM_REQ,ITEM_TRADE,ITEM_TRADE)        sm.sendNext(req)    elif sm.hasItem(ITEM_TRADE,ITEM_REQ):        if sm.getEmptyInventorySlots(2)>= 1:            if PERCENT == 100:                Magnificent = "#fUI/UIWindow2.img/QuestIcon/4/0#\r\n\r\n#i%s#\t#b#e#z%s##n#k \r\n" % (VON_BON[len(VON_BON)-1],VON_BON[len(VON_BON)-1])                chr.addItemToInventory(VON_BON[len(VON_BON)-1],1)                sm.consumeItem(ITEM_TRADE,ITEM_REQ)                sm.sendNext(Magnificent)            else:                OTHER = random.randint(VON_BON[0],VON_BON[len(VON_BON)-2])                Other = "#fUI/UIWindow2.img/QuestIcon/4/0#\r\n\r\n#i%s#\t#b#e#z%s##n#k \r\n" % (OTHER,OTHER)                chr.addItemToInventory(OTHER,1,"day",90)                sm.consumeItem(ITEM_TRADE,ITEM_REQ)                sm.sendNext(Other)        else:            sm.sendSayOkay("Please make more space in your USE inventory.")elif selection == 1:    sm.resetParam()    list_item = "The Item will cost you #r%s #i%s# #b#e#z%s##n#k\r\n" % (ITEM_REQ,ITEM_TRADE,ITEM_TRADE)    for i in range(len(VON_BON)):        list_item += "#i%s#\t#b#e#z%s##n#k \r\n" % (VON_BON[i],VON_BON[i])    sm.sendNext(list_item)            